// Cobrador de promessas (08/10/2026): pede à IA para separar, das frases de intenção, o que é compromisso pessoal que ficou sem lembrete.
const NL = String.fromCharCode(10);
const lista = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(p => p && p.autor && Array.isArray(p.itens) && p.itens.length);
const hoje = DateTime.now().setZone('America/Sao_Paulo').setLocale('pt-BR');
const sistema = [
  'Você ajuda a Dina, assistente pessoal no WhatsApp, a lembrar das coisas que a pessoa DISSE que precisava fazer e que ficaram sem lembrete.',
  'Hoje é ' + hoje.toFormat("cccc, dd/LL/yyyy") + '. As datas das mensagens estão em dd/mm (ano atual).',
  'Para cada mensagem, decida se ela contém um COMPROMISSO PESSOAL concreto da própria pessoa (ex.: ligar para alguém, devolver algo, pagar alguém, marcar consulta, resolver um conserto, responder alguém) que NÃO virou lembrete, tarefa, compromisso, conta ou gasto. Use o campo "criados" (lembretes, tarefas e compromissos da pessoa nos 3 dias antes e logo depois da mensagem, com status, mais contas e gastos registrados na hora) e a "resposta" do assistente para saber o que já foi agendado ou feito; se algo parecido já existe, NÃO é promessa.',
  'NÃO é promessa: pedidos ou perguntas ao assistente, registros de gasto, consultas de saldo, coisas já agendadas, rotina genérica (trabalhar, dormir), desabafos e frases vagas sem ação clara.',
  'Se uma mensagem tiver várias coisas e só uma ficou sem agendamento, marque promessa=true com essa ação.',
  'Responda SOMENTE com JSON válido, sem texto fora dele: {"itens":[{"msg_id":123,"promessa":true,"acao":"ligar para o encanador","prazo":"AAAA-MM-DD"}]}.',
  'Regras de "acao": verbo no infinitivo, até 60 caracteres, em minúsculas, sem números de documento ou valores. "prazo": a data em que a pessoa disse que faria (ex.: "amanhã" → dia seguinte à mensagem), ou null se não disse. Inclua TODAS as mensagens recebidas no array, com promessa=false quando não for o caso.'
].join(NL);
const out = [];
for (const p of lista) {
  const ids = p.itens.map(x => Number(x.msg_id));
  const user = 'Mensagens de ' + p.autor + ':' + NL + JSON.stringify(p.itens.map(x => ({ msg_id: x.msg_id, quando: x.quando, texto: x.texto, resposta: x.resposta, criados: x.criados })));
  out.push({ json: { autor: p.autor, numero: p.numero, ids, tarefa: 'simples', origem: 'promessas_triagem', sistema, mensagens: [{ role: 'user', content: user }], max_tokens: 900 } });
}
return out;

// Lê o JSON da IA e prepara o registro (o que não vier como promessa é descartado e não volta a ser analisado).
const out = [];
$input.all().forEach((it, i) => {
  const r = it.json || {};
  const ped = $('Montar triagem').all()[i].json;
  if (!r.ok) return;
  let txt = String(r.texto || '').replace(/^```[a-z]*\s*|```\s*$/g, '').trim();
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  if (a < 0 || b < a) return;
  let obj = null;
  try { obj = JSON.parse(txt.slice(a, b + 1)); } catch (e) { return; }
  const itens = (Array.isArray(obj.itens) ? obj.itens : []).filter(x => x && ped.ids.includes(Number(x.msg_id))).map(x => ({ msg_id: Number(x.msg_id), promessa: x.promessa === true, acao: String(x.acao || '').slice(0, 80), prazo: /^\d{4}-\d{2}-\d{2}$/.test(String(x.prazo || '')) ? x.prazo : null }));
  out.push({ json: { p_autor: ped.autor, p_numero: ped.numero, p_ids: ped.ids, p_itens: itens } });
});
return out;

// Uma pergunta da Dina por pessoa (no máximo 1 por dia).
const ZW = String.fromCharCode(8203), NL = String.fromCharCode(10);
const lista = $input.all().map(i => i.json).filter(x => x && x.autor && x.numero && x.texto);
return lista.map(x => ({ json: { number: String(x.numero), text: ZW + '*⏰ Dina*' + NL + x.texto, delay: 1200 } }));
